import ctypes
import numpy as np

# Load the libraries
ctypes.CDLL('/usr/local/gsl/lib/libgslcblas.so', mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL('/usr/local/gsl/lib/libgsl.so')

# Define the function prototype
norm_types = {
    'none': 0,
    'schmidt': 1,
    'spharm': 2,
    'full': 3
}
gsl.gsl_sf_legendre_array.argtypes = [ctypes.c_int, ctypes.c_size_t, ctypes.c_double, ctypes.POINTER(ctypes.c_double)]
gsl.gsl_sf_legendre_array.restype = ctypes.c_int

def compute_legendre_polynomials(norm, lmax, x, csphase):
    if not (-1.0 <= x <= 1.0):
        raise ValueError('Input x must be within the range [-1, 1]')

    norm_value = norm_types.get(norm)
    if norm_value is None:
        raise ValueError('Invalid norm type')

    nlm = (lmax + 1) * (lmax + 2) // 2
    result_array = (ctypes.c_double * nlm)()

    status = gsl.gsl_sf_legendre_array(norm_value, lmax, x, result_array)
    if status != 0:
        raise RuntimeError('GSL function call failed')

    return np.ctypeslib.as_array(result_array, shape=(nlm,))

def assert_test():
    # Test case 1: Basic functionality
    result = compute_legendre_polynomials('none', 2, 0.5, 1.0)
    expected = np.array([1.0, 0.5, 0.86602540378, -0.125, 0.75, 0.64951905284])
    assert np.allclose(result, expected, atol=1e-7), f"Test case 1 failed: {result} != {expected}"

    # Test case 2: Error handling for invalid norm
    try:
        compute_legendre_polynomials('invalid', 2, 0.5, 1.0)
    except ValueError as e:
        assert str(e) == 'Invalid norm type', f"Test case 2 failed: {str(e)}"

    # Test case 3: Error handling for x out of range
    try:
        compute_legendre_polynomials('none', 2, 2.0, 1.0)  # x out of range
    except ValueError as e:
        assert str(e) == 'Input x must be within the range [-1, 1]', f"Test case 3 failed: {str(e)}"

if __name__ == "__main__":
    assert_test()
